struct BorrowedData<'a> {
    data: &'a [u8],
}

fn main() {
    let bytes = b"Hello, World!";
    let borrowed = BorrowedData { data: bytes };

    // Attempt to return a String derived from the borrowed slice
    // This will only compile if the String is moved before the borrowed slice is dropped
    let result = String::from_utf8(borrowed.data.to_vec()).unwrap();

    // Assert that the program compiles and runs correctly
    assert_eq!(result, "Hello, World!");

    // Drop the borrowed slice here to ensure the String was moved before
    drop(borrowed);

    println!("Ownership test passed");
}
